INSERT OR IGNORE INTO sky_settings(key,value) VALUES
 ('organization_name','SKY FIRST NETWORK'),('organization_descriptor','Mạng lưới Giáo dục & Phát triển Cộng đồng Sky First'),('tagline','Giáo dục · Văn hóa · Cộng đồng'),('footer_description','Khởi nguồn từ giáo dục miễn phí 2025 · Phát triển từ tri thức, văn hóa và cộng đồng.'),('brand_logo_url','/assets/branding/sky-first-main-logo.png'),('brand_favicon_url','/assets/branding/sky-first-main-logo.png'),('theme_sky','#159BFF'),('theme_blue','#0648B8'),('theme_navy','#062A67'),('theme_soft','#EAF7FF'),('card_radius','22'),('contact_email','skyfirst.ec@gmail.com'),('support_email','hotro.sfn@gmail.com'),('hotline','0924 910 210'),('facebook_url','https://www.facebook.com/skyfirstnetwork'),('instagram_url','https://www.instagram.com/sfn.network'),('tiktok_url','https://www.tiktok.com/@sfn.network'),('donation_verified','0'),('donation_bank',''),('donation_account',''),('donation_owner',''),('donation_contact_name',''),('donation_contact_phone',''),('donation_contact_email','');
INSERT OR IGNORE INTO sky_portals(slug,title,description,url,sort_order) VALUES
 ('academic','Cổng Học liệu & Học thuật','Học liệu, hoạt động học thuật và thông tin chuyên môn.','https://academic.skyfirst.io.vn/',1),
 ('member','Cổng Thành viên','Không gian kết nối dành cho thành viên của Sky First.','https://member.skyfirst.io.vn/',2),
 ('volunteer','Cổng Tình nguyện viên','Thông tin tham gia và phối hợp tình nguyện.','https://v.skyfirst.io.vn/',3),
 ('information','Sky First Network — Cổng Thành viên & Tình nguyện viên','Cổng thông tin phục vụ thành viên và tình nguyện viên.','https://ctt.skyfirst.io.vn/',4);
INSERT OR IGNORE INTO sky_pages(slug,locale,title,summary,body_html) VALUES
 ('gioi-thieu','vi','Giới thiệu về Sky First','Thông tin nền tảng về định hướng, tổ chức và nguyên tắc công khai.','<p>Sky First Network là không gian kết nối giáo dục, văn hóa và cộng đồng. Mạng lưới phát triển các chương trình theo năng lực thực tế, tôn trọng người học và trách nhiệm với cộng đồng.</p>'),
 ('gioi-thieu','en','About Sky First','Foundational information on direction, organisation and public principles.','<p>Sky First Network connects education, culture and community. Its programmes are developed around real capacity, respect for learners and responsibility to the community.</p>'),
 ('hoat-dong','vi','Chương trình hoạt động','Các hướng triển khai được công bố theo từng thời điểm.','<p>Hoạt động được tổ chức theo năm trụ cột: giáo dục; phát triển người trẻ; tình nguyện và cộng đồng; kết nối và hợp tác; truyền thông.</p>'),
 ('hoat-dong','en','Programmes','Activity directions are published as they are confirmed.','<p>Activities are organised around five pillars: education; youth development; volunteering and community; connection and partnership; communication.</p>'),
 ('don-vi','vi','Các đơn vị trực thuộc','Không gian chuyên môn hoạt động theo định hướng chung.','<p>Mỗi đơn vị có lĩnh vực riêng, trách nhiệm rõ ràng và tuân thủ định hướng chung của Sky First Network.</p>'),
 ('don-vi','en','Member units','Specialist spaces operating under a shared direction.','<p>Each unit has its own field, clear responsibility and follows Sky First Network’s shared direction.</p>');
-- 33 official questions, Vietnamese
INSERT OR IGNORE INTO sky_topics(slug,locale,number,question,answer_html) VALUES
 ('sky-first-la-gi','vi',1,'Sky First Network là gì?','<p>Sky First Network là Mạng lưới Giáo dục &amp; Phát triển Cộng đồng Sky First; một không gian kết nối các hoạt động giáo dục, văn hóa và cộng đồng.</p>'),
 ('hinh-thanh','vi',2,'Sky First Network được hình thành như thế nào?','<p>Mạng lưới khởi nguồn từ các hoạt động giáo dục miễn phí năm 2025 và tiếp tục phát triển theo nhu cầu thực tế của cộng đồng.</p>'),
 ('y-nghia-ten','vi',3,'Tên gọi Sky First có ý nghĩa gì?','<p>Sky First gợi mở tinh thần hướng lên, chủ động học hỏi và đặt nền tảng cho những cơ hội phát triển tích cực.</p>'),
 ('tam-nhin','vi',4,'Tầm nhìn của Sky First Network là gì?','<p>Xây dựng một không gian học tập, kết nối và đóng góp cộng đồng có trách nhiệm, dễ tiếp cận và có khả năng phát triển bền vững.</p>'),
 ('su-menh','vi',5,'Sứ mệnh của Sky First Network là gì?','<p>Kết nối cơ hội học tập, trải nghiệm, văn hóa và đóng góp cộng đồng để mỗi người có thể phát triển năng lực và tham gia có ý nghĩa.</p>'),
 ('gia-tri-cot-loi','vi',6,'Các giá trị cốt lõi là gì?','<p>Minh bạch; tôn trọng; chủ động học hỏi; trách nhiệm; hợp tác và hướng đến giá trị cộng đồng.</p>'),
 ('dinh-huong-2026','vi',7,'Định hướng từ năm 2026 là gì?','<p>Chuẩn hóa hoạt động, củng cố hệ thống quản trị, phát triển học liệu và mở rộng hợp tác phù hợp với năng lực thực tế.</p>'),
 ('nam-linh-vuc','vi',8,'Sky First hoạt động trong những lĩnh vực nào?','<p>Giáo dục; phát triển người trẻ; tình nguyện và cộng đồng; kết nối và hợp tác; truyền thông.</p>'),
 ('doi-tuong','vi',9,'Đối tượng tham gia là ai?','<p>Người học, tình nguyện viên, thành viên nòng cốt, chuyên gia, tổ chức và cá nhân có mong muốn đồng hành phù hợp.</p>'),
 ('chuong-trinh','vi',10,'Sky First hiện có chương trình nào?','<p>Chương trình chỉ được công bố khi có đầu mối phụ trách, phạm vi hoạt động và thông tin xác nhận rõ ràng.</p>'),
 ('lop-hoc','vi',11,'Có lớp học hoặc hoạt động học thuật nào không?','<p>Có thể triển khai lớp học, học liệu, workshop và hoạt động học thuật theo từng thông báo chính thức.</p>'),
 ('cot-moc','vi',12,'Các cột mốc được công bố như thế nào?','<p>Chỉ các cột mốc đã được xác nhận và phù hợp phạm vi công khai mới được đăng tải.</p>'),
 ('co-cau','vi',13,'Cơ cấu tổ chức gồm những gì?','<p>Cơ cấu gồm Ban Điều hành, nhóm phụ trách chương trình, các đơn vị trực thuộc và các đầu mối theo nhiệm vụ.</p>'),
 ('don-vi-truc-thuoc','vi',14,'Các đơn vị trực thuộc được xác định ra sao?','<p>Đơn vị được công bố khi có phạm vi chuyên môn, người phụ trách và cách thức liên hệ chính thức.</p>'),
 ('sfec','vi',15,'Câu lạc bộ Tiếng Anh The Sky First là gì?','<p>Đây là không gian tiếng Anh, giáo dục cộng đồng, lớp học, học liệu và hỗ trợ người học theo thông tin được công bố.</p>'),
 ('nhan-su','vi',16,'Đội ngũ được công khai thế nào?','<p>Chỉ công khai thông tin nhân sự khi có sự đồng ý, vai trò rõ ràng và phù hợp với nguyên tắc bảo vệ thông tin cá nhân.</p>'),
 ('ca-nhan','vi',17,'Có công khai cá nhân đại diện không?','<p>Không mặc định. Thông tin cá nhân chỉ được đăng khi cần thiết, được xác nhận và có sự đồng ý phù hợp.</p>'),
 ('doi-tac','vi',18,'Đối tác được công bố như thế nào?','<p>Chỉ công bố đơn vị hoặc cá nhân đã xác nhận hợp tác và được phép công khai.</p>'),
 ('cach-tham-gia','vi',19,'Có thể tham gia bằng những cách nào?','<p>Có thể đăng ký quan tâm với vai trò Core Team, tình nguyện viên, người học hoặc đồng hành chuyên môn.</p>'),
 ('dang-ky','vi',20,'Đăng ký ở đâu?','<p>Đăng ký tại mục Gia nhập &amp; Hợp tác hoặc biểu mẫu chính thức theo từng chương trình.</p>'),
 ('hop-tac','vi',21,'Các hình thức hợp tác là gì?','<p>Có thể gồm phối hợp chuyên môn, tổ chức hoạt động, hỗ trợ nguồn lực, học liệu hoặc truyền thông phù hợp.</p>'),
 ('lien-he-hop-tac','vi',22,'Liên hệ hợp tác bằng cách nào?','<p>Dùng biểu mẫu liên hệ chính thức để yêu cầu được chuyển đúng đầu mối phụ trách.</p>'),
 ('tin-tuc','vi',23,'Tin tức và hoạt động được đăng thế nào?','<p>Chỉ nội dung đã duyệt, có nguồn và phù hợp phạm vi công khai mới được xuất bản.</p>'),
 ('thu-vien-anh','vi',24,'Thư viện hình ảnh có nguyên tắc gì?','<p>Chỉ sử dụng hình ảnh thật, được phép công bố; không dùng ảnh minh họa như tư liệu hoạt động.</p>'),
 ('tai-lieu','vi',25,'Tài liệu công khai gồm những gì?','<p>Gồm các tài liệu được phép công bố; phiên bản, nguồn và thời điểm cập nhật phải rõ ràng.</p>'),
 ('gcn','vi',26,'Cổng tra cứu GCN điện tử dùng để làm gì?','<p>Đây là cổng xác thực tập trung cho kết quả đã được công bố từ các website và ứng dụng thuộc Sky First Network.</p>'),
 ('cong-he-thong','vi',27,'Hệ thống cổng thông tin gồm gì?','<p>Gồm các cổng được Sky First Network công bố chính thức và liên kết từ trang này.</p>'),
 ('lien-he','vi',28,'Kênh liên hệ chính thức là gì?','<p>Email chính: skyfirst.ec@gmail.com; hỗ trợ: hotro.sfn@gmail.com; Hotline/Zalo: 0924 910 210.</p>'),
 ('logo','vi',29,'Quy chuẩn sử dụng logo là gì?','<p>Không bóp méo, đổi màu tùy tiện, thêm hiệu ứng hoặc sử dụng logo ngoài phạm vi được xác nhận.</p>'),
 ('thong-diep','vi',30,'Thông điệp trang chủ là gì?','<p>Phát triển từ tri thức, văn hóa và cộng đồng.</p>'),
 ('hanh-dong-chinh','vi',31,'Các hành động chính trên trang chủ là gì?','<p>Tìm hiểu định hướng; xem chương trình; gửi thông tin tham gia; tra cứu xác thực; kết nối đồng hành.</p>'),
 ('khong-cong-khai','vi',32,'Những gì không được công khai?','<p>Dữ liệu cá nhân, hồ sơ nội bộ, thông tin chưa xác nhận, dữ liệu tài chính nhạy cảm và nội dung không có quyền công bố.</p>'),
 ('phap-ly','vi',33,'Thông tin pháp lý được trình bày thế nào?','<p>Website chỉ công bố thông tin đúng phạm vi, không suy diễn tư cách pháp lý hoặc công bố thông tin chưa có xác nhận chính thức.</p>');
-- English equivalents for the same public knowledge base
INSERT OR IGNORE INTO sky_topics(slug,locale,number,question,answer_html) SELECT slug,'en',number,
 CASE number WHEN 1 THEN 'What is Sky First Network?' WHEN 2 THEN 'How was it formed?' WHEN 3 THEN 'What does the name mean?' WHEN 4 THEN 'What is its vision?' WHEN 5 THEN 'What is its mission?' WHEN 6 THEN 'What are its core values?' WHEN 7 THEN 'What is the direction from 2026?' WHEN 8 THEN 'What are its activity fields?' WHEN 9 THEN 'Who can take part?' WHEN 10 THEN 'Which programmes are available?' WHEN 11 THEN 'Are there classes or academic activities?' WHEN 12 THEN 'How are milestones published?' WHEN 13 THEN 'What is the organisational structure?' WHEN 14 THEN 'How are member units identified?' WHEN 15 THEN 'What is The Sky First English Club?' WHEN 16 THEN 'How is the team presented publicly?' WHEN 17 THEN 'Are individual representatives published?' WHEN 18 THEN 'How are partners published?' WHEN 19 THEN 'How can people participate?' WHEN 20 THEN 'Where can people register?' WHEN 21 THEN 'What forms of partnership are possible?' WHEN 22 THEN 'How can partnership requests be sent?' WHEN 23 THEN 'How are news and activities published?' WHEN 24 THEN 'What is the image-library rule?' WHEN 25 THEN 'What public documents are available?' WHEN 26 THEN 'What is the electronic verification portal for?' WHEN 27 THEN 'Which system portals are official?' WHEN 28 THEN 'What are the official contact channels?' WHEN 29 THEN 'What are the logo-use rules?' WHEN 30 THEN 'What is the homepage message?' WHEN 31 THEN 'What are the homepage actions?' WHEN 32 THEN 'What is not made public?' WHEN 33 THEN 'How is legal information presented?' END,
 CASE number WHEN 1 THEN '<p>Sky First Network is a network for education and community development, connecting education, culture and community activities.</p>' WHEN 2 THEN '<p>It began with free education activities in 2025 and continues to develop around real community needs.</p>' WHEN 3 THEN '<p>Sky First represents aspiration, proactive learning and a foundation for positive development opportunities.</p>' WHEN 4 THEN '<p>To build an accessible, responsible and sustainable space for learning, connection and community contribution.</p>' WHEN 5 THEN '<p>To connect learning, experience, culture and community contribution so people can develop capacity and participate meaningfully.</p>' WHEN 6 THEN '<p>Transparency, respect, proactive learning, responsibility, cooperation and community value.</p>' WHEN 7 THEN '<p>Standardise operations, strengthen governance, develop learning resources and expand partnerships that match real capacity.</p>' WHEN 8 THEN '<p>Education; youth development; volunteering and community; connection and partnership; communication.</p>' WHEN 9 THEN '<p>Learners, volunteers, core members, specialists, organisations and individuals whose participation is appropriate.</p>' WHEN 10 THEN '<p>Programmes are announced only after their responsible contact, scope and official information are confirmed.</p>' WHEN 11 THEN '<p>Classes, learning resources, workshops and academic activities may be offered through official notices.</p>' WHEN 12 THEN '<p>Only confirmed milestones appropriate for public release are published.</p>' WHEN 13 THEN '<p>The structure includes the Executive Board, programme teams, member units and role-based contacts.</p>' WHEN 14 THEN '<p>A unit is announced when its scope, responsible person and official contact method are clear.</p>' WHEN 15 THEN '<p>A space for English, community education, classes, learning resources and learner support according to published information.</p>' WHEN 16 THEN '<p>Team information is published only with consent, a clear role and respect for personal-data protection.</p>' WHEN 17 THEN '<p>Not by default. Personal information is only published where needed, confirmed and appropriately consented to.</p>' WHEN 18 THEN '<p>Only partners with confirmed collaboration and permission for public disclosure are published.</p>' WHEN 19 THEN '<p>People can express interest as Core Team members, volunteers, learners or professional partners.</p>' WHEN 20 THEN '<p>Use Join &amp; Partner or the official form for the relevant programme.</p>' WHEN 21 THEN '<p>Professional coordination, activity delivery, resource support, learning resources or appropriate communication.</p>' WHEN 22 THEN '<p>Use the official contact form so the request reaches the responsible contact.</p>' WHEN 23 THEN '<p>Only reviewed content with a source and suitable public scope is published.</p>' WHEN 24 THEN '<p>Only real images approved for publication are used; illustrative images are not presented as activity records.</p>' WHEN 25 THEN '<p>Only documents approved for public release are listed, with version, source and update time stated clearly.</p>' WHEN 26 THEN '<p>A central verification portal for published results from websites and applications of Sky First Network.</p>' WHEN 27 THEN '<p>Only portals officially announced and linked from this website are part of the system.</p>' WHEN 28 THEN '<p>Main email: skyfirst.ec@gmail.com; support: hotro.sfn@gmail.com; Hotline/Zalo: 0924 910 210.</p>' WHEN 29 THEN '<p>Do not distort, recolour arbitrarily, add effects to, or use the logo outside its confirmed scope.</p>' WHEN 30 THEN '<p>Developed through knowledge, culture and community.</p>' WHEN 31 THEN '<p>Learn about direction; see programmes; submit participation information; verify records; connect for partnership.</p>' WHEN 32 THEN '<p>Personal data, internal records, unconfirmed information, sensitive financial data and content without publication rights.</p>' WHEN 33 THEN '<p>The website publishes information only within its verified scope and does not infer legal status or disclose unconfirmed claims.</p>' END
 FROM sky_topics WHERE locale='vi';
